// summaryDeadlineResolver is package-level so tests can substitute the
// resolution policy without touching settings or stderr.
var summaryDeadlineResolver = func(errW io.Writer) (time.Duration, bool) {
    s, _ := settings.Load() //nolint:errcheck // empty settings on error is acceptable
    return resolveSummaryDeadlineInputs{
        settings:    s.SummaryTimeoutValue(),
        interactive: isTerminalWriter(errW),
    }.resolve()
}

func generateCheckpointAISummary(
    ctx context.Context,
    errW io.Writer,
    scopedTranscript []byte,
    filesTouched []string,
    agentType types.AgentType,
) (*checkpoint.Summary, error) {
    progressWriter := newSummaryProgressWriter(errW)
    progressFn := agent.ProgressFn(func(p agent.GenerationProgress) { progressWriter.handle(p) })

    deadline, has := summaryDeadlineResolver(errW)

    runCtx := ctx
    if has {
        // For non-interactive mode (and only there), use idle-based cancellation.
        // For an explicit settings override, use a hard wall-clock deadline.
        if !isTerminalWriter(errW) && settingsTimeoutUnset(ctx) {
            wctx, _, stop := startIdleWatchdog(ctx, deadline, &progressWriter.lastIdle)
            defer stop()
            runCtx = wctx
        } else {
            wctx, cancel := context.WithTimeout(ctx, deadline)
            defer cancel()
            runCtx = wctx
        }
    }

    summary, err := generateTranscriptSummary(runCtx, redact.AlreadyRedacted(scopedTranscript), filesTouched, agentType, nil, progressFn)
    if err != nil {
        if errors.Is(err, context.Canceled) || errors.Is(runCtx.Err(), context.Canceled) {
            return nil, fmt.Errorf("summary generation canceled: %w", context.Canceled)
        }
        if errors.Is(err, context.DeadlineExceeded) || errors.Is(runCtx.Err(), context.DeadlineExceeded) {
            return nil, fmt.Errorf("summary generation timed out after %s: %w", formatSummaryTimeout(deadline), context.DeadlineExceeded)
        }
        return nil, err
    }
    return summary, nil
}

// settingsTimeoutUnset returns true when no explicit override is set (so the
// caller should treat the deadline as the non-interactive default and use
// idle-based cancellation rather than wall-clock).
func settingsTimeoutUnset(_ context.Context) bool {
    s, _ := settings.Load() //nolint:errcheck
    return s.SummaryTimeoutValue() == 0
}
```

