func generateCheckpointAISummary(ctx context.Context, errW io.Writer, scopedTranscript []byte, filesTouched []string, agentType types.AgentType) (*checkpoint.Summary, error) {
	// Create progress writer so the user sees phase updates on stderr.
	progressWriter := newSummaryProgressWriter(errW)

	// Resolve deadline based on TTY + settings.
	deadline, hasDeadline := summaryDeadlineResolver(errW)

	// Apply deadline according to resolution mode.
	runCtx := ctx
	if hasDeadline {
		if !isTerminalWriter(errW) && settingsTimeoutUnset() {
			// Non-interactive default: cancel only when the model goes idle.
			var stop func()
			runCtx, _, stop = startIdleWatchdog(ctx, deadline, &progressWriter.lastActivity)
			defer stop()
		} else {
			// Explicit settings override or interactive with override: hard wall-clock.
			var cancel context.CancelFunc
			runCtx, cancel = context.WithTimeout(ctx, deadline)
			defer cancel()
		}
	}

	// scopedTranscript is read from checkpoint storage, which redacts on write.
	summary, err := generateTranscriptSummary(
		runCtx,
		redact.AlreadyRedacted(scopedTranscript),
		filesTouched,
		agentType,
		nil, // generator (use default)
		agent.ProgressFn(func(p agent.GenerationProgress) { progressWriter.handle(p) }),
	)
	if err != nil {
		if errors.Is(err, context.Canceled) || errors.Is(runCtx.Err(), context.Canceled) {
			return nil, fmt.Errorf("summary generation canceled: %w", context.Canceled)
		}
		if errors.Is(err, context.DeadlineExceeded) || errors.Is(runCtx.Err(), context.DeadlineExceeded) {
			return nil, fmt.Errorf("summary generation timed out after %s: %w", formatSummaryTimeout(deadline), context.DeadlineExceeded)
		}
		return nil, err
	}

	return summary, nil
}

