func generateCheckpointAISummary(ctx context.Context, errW io.Writer, scopedTranscript []byte, filesTouched []string, agentType types.AgentType) (*checkpoint.Summary, time.Duration, error) {
	progressWriter := newSummaryProgressWriter(errW)

	// Resolve deadline once — avoids repeated settings.Load() calls.
	resolved := summaryDeadlineResolver(errW)

	runCtx := ctx
	switch resolved.mode {
	case deadlineModeIdle:
		var stop func()
		runCtx, _, stop = startIdleWatchdog(ctx, resolved.duration, &progressWriter.lastActivity)
		defer stop()
	case deadlineModeHardClock:
		var cancel context.CancelFunc
		runCtx, cancel = context.WithTimeout(ctx, resolved.duration)
		defer cancel()
	case deadlineModeNone:
		// Interactive: no deadline, user Ctrl+C is the timeout.
	}

	summary, err := generateTranscriptSummary(
		runCtx,
		redact.AlreadyRedacted(scopedTranscript),
		filesTouched,
		agentType,
		nil,
		agent.ProgressFn(func(p agent.GenerationProgress) { progressWriter.handle(p) }),
	)
	if err != nil {
		if errors.Is(err, context.Canceled) || errors.Is(runCtx.Err(), context.Canceled) {
			return nil, resolved.duration, fmt.Errorf("summary generation canceled: %w", context.Canceled)
		}
		if errors.Is(err, context.DeadlineExceeded) || errors.Is(runCtx.Err(), context.DeadlineExceeded) {
			return nil, resolved.duration, fmt.Errorf("summary generation timed out after %s: %w", formatSummaryTimeout(resolved.duration), context.DeadlineExceeded)
		}
		return nil, resolved.duration, err
	}

	return summary, resolved.duration, nil
}

